import random
from itertools import combinations

def has_short_cycle(adj, n, max_len=6):
    # BFS from each vertex to check for cycles of length <= max_len
    for s in range(n):
        # BFS
        dist = {s: 0}
        parent = {s: -1}
        from collections import deque
        q = deque([s])
        while q:
            u = q.popleft()
            if dist[u] >= max_len:
                continue
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u]+1
                    parent[v] = u
                    q.append(v)
                else:
                    # found a cycle
                    if v != parent[u]:
                        cycle_len = dist[u] + dist[v] + 1
                        if cycle_len <= max_len:
                            return True
    return False

def girth_ok(edges, n):
    adj = [set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    # For each edge, remove it and find shortest path; shortest cycle through this edge
    for u,v in edges:
        adj[u].discard(v); adj[v].discard(u)
        # BFS from u to v
        from collections import deque
        dist = {u:0}
        q = deque([u])
        found = None
        while q:
            x = q.popleft()
            if dist[x] >= 6: 
                continue
            for y in adj[x]:
                if y not in dist:
                    dist[y] = dist[x]+1
                    if y == v:
                        found = dist[y]
                        break
                    q.append(y)
            if found: break
        adj[u].add(v); adj[v].add(u)
        if found is not None and found + 1 <= 6:
            return False
    return True

def try_build(n=25, target=31, seed=0):
    random.seed(seed)
    edges = []
    adj = [set() for _ in range(n)]
    candidates = list(combinations(range(n),2))
    random.shuffle(candidates)
    for u,v in candidates:
        # check if adding creates cycle of length <= 6
        # BFS from u avoiding edge (u,v)
        from collections import deque
        dist = {u:0}
        q = deque([u])
        bad = False
        while q:
            x = q.popleft()
            if dist[x] >= 5: continue
            for y in adj[x]:
                if y not in dist:
                    dist[y] = dist[x]+1
                    if y == v and dist[y] <= 5:
                        bad = True; break
                    q.append(y)
            if bad: break
        if v in dist and dist[v] <= 5:
            bad = True
        if not bad:
            edges.append((u,v))
            adj[u].add(v); adj[v].add(u)
            if len(edges) >= target:
                break
    return edges, adj

